function drawTile(x,y,type){let ox=x*T,oy=y*T;const palette={street:'#55574c',rubble:'#59554a',factory:'#4a5147',crater:'#505348',barricade:'#4d5148'};ctx.fillStyle=palette[type]||'#55574c';ctx.fillRect(ox,oy,T,T);ctx.fillStyle='rgba(225,219,190,.035)';for(let i=0;i<5;i++){let px=ox+4+Math.floor(rnd(x+i,y+2)*55),py=oy+4+Math.floor(rnd(y+i,x+5)*55);ctx.fillRect(px,py,2,2)}
if(type==='street'){ctx.fillStyle='#777568';ctx.fillRect(ox+31,oy+4,2,3);ctx.fillRect(ox+32,oy+48,1,7);ctx.fillStyle='#494b42';ctx.fillRect(ox+6,oy+31,9,2)}
if(type==='rubble'){ctx.fillStyle='#777064';ctx.fillRect(ox+9,oy+15,13,7);ctx.fillRect(ox+26,oy+10,9,5);ctx.fillRect(ox+40,oy+32,14,9);ctx.fillStyle='#33372f';ctx.fillRect(ox+11,oy+24,7,5);ctx.fillRect(ox+32,oy+43,12,6);ctx.fillStyle='#89816e';ctx.fillRect(ox+48,oy+13,5,8)}
if(type==='crater'){ctx.fillStyle='#3e423a';ctx.beginPath();ctx.ellipse(ox+34,oy+33,19,13,-.25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#656456';ctx.beginPath();ctx.ellipse(ox+32,oy+30,14,8,-.25,0,Math.PI*2);ctx.fill();ctx.fillStyle='#393d36';ctx.fillRect(ox+25,oy+27,15,4)}
if(type==='factory'){ctx.fillStyle='#333a34';ctx.fillRect(ox+8,oy+12,45,38);ctx.fillStyle='#77786a';ctx.fillRect(ox+5,oy+10,46,5);ctx.fillStyle='#454b43';ctx.fillRect(ox+12,oy+19,9,12);ctx.fillRect(ox+26,oy+19,9,12);ctx.fillRect(ox+40,oy+19,8,12);ctx.fillStyle='#252a26';ctx.fillRect(ox+25,oy+36,11,14);ctx.fillStyle='#6b6b5d';ctx.fillRect(ox+43,oy+2,7,17);ctx.fillRect(ox+40,oy+1,13,4)}
if(type==='barricade'){ctx.fillStyle='#383d36';ctx.fillRect(ox+8,oy+25,48,15);ctx.fillStyle='#786b56';ctx.fillRect(ox+11,oy+22,16,6);ctx.fillRect(ox+29,oy+22,19,6);ctx.fillStyle='#34382f';ctx.fillRect(ox+17,oy+40,6,6);ctx.fillRect(ox+41,oy+40,6,6)}
ctx.strokeStyle='rgba(21,24,21,.48)';ctx.lineWidth=1;ctx.strokeRect(ox+.5,oy+.5,T-1,T-1)}
function drawObjective(o){let cx=o.x*T+32,cy=o.y*T+32;ctx.save();ctx.globalAlpha=.18;ctx.fillStyle=o.owner?factionData[o.owner].color:'#e4ba60';ctx.beginPath();ctx.arc(cx,cy,26,0,Math.PI*2);ctx.fill();ctx.restore();ctx.strokeStyle=o.owner?factionData[o.owner].color:'#ddbb65';ctx.lineWidth=2;ctx.setLineDash([4,3]);ctx.beginPath();ctx.arc(cx,cy,24,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#252821';ctx.fillRect(cx-8,cy-15,16,26);ctx.strokeStyle='#e5c46e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx-1,cy+9);ctx.lineTo(cx-1,cy-15);ctx.stroke();ctx.fillStyle=o.owner?factionData[o.owner].color:'#e5c46e';ctx.beginPath();ctx.moveTo(cx,cy-15);ctx.lineTo(cx+12,cy-11);ctx.lineTo(cx,cy-7);ctx.fill();ctx.font='8px "DM Mono"';ctx.textAlign='center';ctx.fillStyle='#ead9ad';ctx.fillText(o.name.toUpperCase(),cx,cy+35)}
function drawUnit(u){let x=u.x*T,y=u.y*T,c=factionData[u.side].color,hostile=u.side!==player;ctx.save();ctx.translate(x,y);if(selected===u.id){ctx.strokeStyle='#f0cb69';ctx.lineWidth=2;ctx.strokeRect(4,4,T-8,T-8)}
// Ground shadow
ctx.fillStyle='rgba(16,18,16,.55)';ctx.fillRect(13,46,40,9);
if(u.type==='rifle'){ctx.fillStyle='#33382f';ctx.fillRect(20,19,25,29);ctx.fillStyle=c;ctx.fillRect(22,18,21,24);ctx.fillStyle=hostile?'#d8c99e':'#d7d1b3';ctx.fillRect(26,12,13,10);ctx.fillStyle='#38392f';ctx.fillRect(25,10,14,5);ctx.fillStyle='#292c26';ctx.fillRect(44,23,12,3);ctx.fillRect(48,21,3,7);ctx.fillStyle='#ddd0ac';ctx.fillRect(28,16,3,3);}
if(u.type==='tank'){ctx.fillStyle='#32372e';ctx.fillRect(9,24,47,24);ctx.fillStyle='#4b5143';for(let i=0;i<6;i++)ctx.fillRect(11+i*7,45,4,5);ctx.fillStyle=c;ctx.fillRect(13,25,38,18);ctx.fillStyle=hostile?'#91865e':'#9d6754';ctx.fillRect(21,17,20,15);ctx.fillStyle='#5e6150';ctx.fillRect(35,21,22,5);ctx.fillStyle='#222720';ctx.fillRect(52,19,9,3);ctx.fillStyle='#d2c99f';ctx.fillRect(23,19,5,3);}
if(u.type==='gun'){ctx.fillStyle='#363a31';ctx.fillRect(18,34,29,12);ctx.fillStyle=c;ctx.fillRect(24,22,17,14);ctx.fillStyle='#787764';ctx.fillRect(29,15,5,25);ctx.fillRect(27,39,2,12);ctx.fillRect(38,39,2,12);ctx.fillStyle='#272b25';ctx.fillRect(22,45,22,5);ctx.fillStyle='#c9bd91';ctx.fillRect(29,25,5,5);}
// Unit health bar
ctx.fillStyle='#1e211d';ctx.fillRect(10,6,44,5);ctx.fillStyle=u.hp/u.maxHp<.35?'#d26150':'#a7bd78';ctx.fillRect(11,7,42*(u.hp/u.maxHp),3);if(u.attacked){ctx.fillStyle='#d0c6a9';ctx.font='9px "DM Mono"';ctx.textAlign='right';ctx.fillText('F',56,60)}ctx.restore()}
function render(){if(!terrain.length)return;ctx.clearRect(0,0,canvas.width,canvas.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++)drawTile(x,y,terrain[y][x]);let u=units.find(v=>v.id===selected);if(u&&u.side===player&&mode==='move'){let d=reachable(u);for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(d[y][x]>0&&d[y][x]<=u.moveLeft){ctx.fillStyle='rgba(110,157,174,.22)';ctx.fillRect(x*T+2,y*T+2,T-4,T-4);ctx.strokeStyle='rgba(136,188,203,.75)';ctx.strokeRect(x*T+4,y*T+4,T-8,T-8)}}if(u&&u.side===player&&mode==='fire'){for(const target of units)if(target.side!==player&&inRange(u,target)){ctx.fillStyle='rgba(196,76,62,.13)';ctx.fillRect(target.x*T+2,target.y*T+2,T-4,T-4);ctx.strokeStyle='rgba(216,102,83,.9)';ctx.lineWidth=2;ctx.strokeRect(target.x*T+4,target.y*T+4,T-8,T-8)}}objectives.forEach(drawObjective);units.forEach(drawUnit);ctx.fillStyle='rgba(230,220,192,.65)';ctx.font='9px "DM Mono"';ctx.textAlign='left';for(let x=0;x<W;x++)ctx.fillText(String.fromCharCode(65+x),x*T+5,canvas.height-4)}
document.querySelectorAll('[data-faction]').forEach(btn=>btn.addEventListener('click',()=>resetGame(btn.dataset.faction)));document.getElementById('newGameBtn').onclick=()=>{document.getElementById('startOverlay').classList.remove('hidden');document.getElementById('resultOverlay').classList.add('hidden')};document.getElementById('restartBtn').onclick=()=>{document.getElementById('resultOverlay').classList.add('hidden');document.getElementById('startOverlay').classList.remove('hidden')};
// Put a readable deployment map beneath the faction briefing.
makeMap();objectives=[{x:2,y:4,name:'Red October Works',owner:null},{x:6,y:3,name:'Grain Elevator',owner:null},{x:9,y:5,name:'River Crossing',owner:null}];units=[];addUnit('sov','rifle',0,2,'preview-a');addUnit('sov','tank',1,4,'preview-b');addUnit('ger','tank',10,4,'preview-c');addUnit('ger','rifle',11,6,'preview-d');setUI();render();
})();
</script>
</body>
</html>

